import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Set;

public class SecureServer {
    // Define a whitelist of allowed classes to prevent unexpected gadget chains
    private static final Set<String> ALLOWED_CLASSES = Set.of("java.lang.String", "java.util.ArrayList");

    public void startServer(int port) throws IOException {
        ServerSocket serverSocket = new ServerSocket(port);
        while (true) {
            try (Socket socket = serverSocket.accept();
                 // Use a Look-Ahead ObjectInputStream to validate classes before instantiation
                 SecureObjectInputStream ois = new SecureObjectInputStream(socket.getInputStream())) {

                Object obj = ois.readObject();
                System.out.println("Received safe object: " + obj.getClass().getName());
            } catch (Exception e) {
                System.err.println("Blocked potentially malicious input: " + e.getMessage());
            }
        }
    }

    // Custom implementation of ObjectInputStream to enforce a whitelist
    private static class SecureObjectInputStream extends ObjectInputStream {
        public SecureObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Check if the class being deserialized is in our approved whitelist
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
            }
            return super.resolveClass(desc);
        }
    }
}
```

